-- QUERY 1
select * from (
select 1 n, 'A1 module permissions (expect 36)' check_name, (select count(*) from public.permissions where key like 'module.%')::text result
union all select 2, 'A2 module role grants (expect 111)', (select count(*) from public.role_permissions where permission_key like 'module.%')::text
union all select 3, 'A3 module grants per role (expect accounts 10, admin 36, management 33, operations 14, sales 18)', coalesce((select string_agg(role::text||' '||c, ', ' order by role::text) from (select role, count(*) c from public.role_permissions where permission_key like 'module.%' group by role) s), 'none')
union all select 4, 'A4 client roles hold no module permission (expect 0)', (select count(*) from public.role_permissions where permission_key like 'module.%' and role::text in ('client_admin','client_user'))::text
union all select 5, 'A5 sales has module.catalogues, operations does not (expect true,false)', (select (count(*) filter (where role::text='sales'))>0 from public.role_permissions where permission_key='module.catalogues')::text||','||(select (count(*) filter (where role::text='operations'))>0 from public.role_permissions where permission_key='module.catalogues')::text
union all select 6, 'A6 RLS on for the 3 new tables (expect 3)', (select count(*) from pg_class where oid in (to_regclass('public.campaign_companies'), to_regclass('public.requirement_events'), to_regclass('public.site_banners')) and relrowsecurity)::text
union all select 7, 'A7 campaigns.company_id nullable (expect YES)', coalesce((select is_nullable from information_schema.columns where table_schema='public' and table_name='campaigns' and column_name='company_id'), 'MISSING')
union all select 8, 'A8 policies per table (expect campaign_companies 2, campaign_events 2, campaign_products 3, campaigns 3, requirement_events 2, site_banners 3)', coalesce((select string_agg(tablename||' '||c, ', ' order by tablename) from (select tablename, count(*) c from pg_policies where schemaname='public' and tablename in ('campaign_companies','campaigns','campaign_products','campaign_events','requirement_events','site_banners') group by tablename) s), 'none')
union all select 9, 'A9 client sees only catalogues assigned to their company and published (expect true)', coalesce((select (qual like '%campaign_companies%' and qual like '%client_company_id()%' and qual like '%published_to_client_at IS NOT NULL%')::text from pg_policies where schemaname='public' and tablename='campaigns' and policyname='campaigns_select_client'), 'MISSING')
union all select 10, 'A10 client sees only published offerings inside client_products (expect true)', coalesce((select (qual like '%published%' and qual like '%client_products%' and qual like '%campaign_companies%')::text from pg_policies where schemaname='public' and tablename='campaign_products' and policyname='campaign_products_select_client'), 'MISSING')
union all select 11, 'A11 catalogue writes need the Catalogues module, three tables (expect 3)', (select count(*) from pg_policies where schemaname='public' and policyname in ('campaign_companies_write','campaigns_write','campaign_products_write') and qual like '%module.catalogues%' and with_check like '%module.catalogues%')::text
union all select 12, 'A12 requirement_events: clients see only visible events of their own company (expect true)', coalesce((select (qual like '%visible_to_client%' and qual like '%client_company_id()%')::text from pg_policies where schemaname='public' and tablename='requirement_events' and policyname='requirement_events_select_client'), 'MISSING')
union all select 13, 'A13 requirement_events has no insert/update/delete policy (expect 0)', (select count(*) from pg_policies where schemaname='public' and tablename='requirement_events' and cmd <> 'SELECT')::text
union all select 14, 'A14 live banners only for anon, staff-only writes (expect true,true)', coalesce((select (qual like '%is_active%' and qual like '%Asia/Kolkata%' and roles::text like '%anon%')::text from pg_policies where schemaname='public' and tablename='site_banners' and policyname='site_banners_select_live'), 'MISSING')||','||coalesce((select (qual like '%is_internal()%' and qual like '%module.catalogues%' and roles::text not like '%anon%')::text from pg_policies where schemaname='public' and tablename='site_banners' and policyname='site_banners_write'), 'MISSING')
union all select 15, 'A15 workflow functions are SECURITY DEFINER with a fixed search_path (expect 4)', (select count(*) from pg_proc where pronamespace='public'::regnamespace and proname in ('requirement_transition','requirement_add_internal_note','quotation_requirement_guard','quotation_requirement_sync') and prosecdef and array_to_string(proconfig, ',') like '%search_path=public%')::text
union all select 16, 'A16 anon cannot execute the two requirement RPCs (expect false,false)', coalesce(has_function_privilege('anon', to_regprocedure('public.requirement_transition(uuid,text,text,boolean)')::oid, 'execute')::text||','||has_function_privilege('anon', to_regprocedure('public.requirement_add_internal_note(uuid,text)')::oid, 'execute')::text, 'MISSING')
union all select 17, 'A17 workflow stage check lists 12 stages (expect 12)', coalesce((select (length(pg_get_constraintdef(oid)) - length(replace(pg_get_constraintdef(oid), '''::text', '')))/7 from pg_constraint where conname='requirements_workflow_stage_check')::text, 'MISSING')
union all select 18, 'A18 quotation triggers (expect quotations_requirement_guard, quotations_requirement_sync)', coalesce((select string_agg(tgname, ', ' order by tgname) from pg_trigger where not tgisinternal and tgname in ('quotations_requirement_guard','quotations_requirement_sync')), 'none')
union all select 19, 'A19 new columns (expect 5)', (select count(*) from information_schema.columns where table_schema='public' and ((table_name='companies' and column_name='allowed_email_domains') or (table_name='product_price_history' and column_name in ('batch_id','rollback_of')) or (table_name='org_settings' and column_name='staff_notification_email') or (table_name='products' and column_name='sales_channel')))::text
union all select 20, 'A20 sales_channel is NOT NULL, default both, with a b2b/b2c check (expect NO, true, true)', coalesce((select is_nullable||', '||(coalesce(column_default,'') like '''both''%')::text from information_schema.columns where table_schema='public' and table_name='products' and column_name='sales_channel'), 'MISSING')||', '||coalesce((select (pg_get_constraintdef(oid) like '%b2b%' and pg_get_constraintdef(oid) like '%b2c%')::text from pg_constraint where conname='products_sales_channel_check'), 'MISSING')
union all select 21, 'A21 client_products view keeps B2C-only products out (expect true)', coalesce((select (pg_get_viewdef(to_regclass('public.client_products')) like '%sales_channel%')::text), 'MISSING')
union all select 22, 'A22 client_products rows (expect 524)', (select count(*) from public.client_products)::text
union all select 23, 'A23 products intact: total | active | HGS- | distinct SKUs | fingerprint (expect 524|524|474|524|60e683d350cd7e55a474b2b86ec87aab)', (select count(*)||'|'||count(*) filter (where status::text='active')||'|'||count(*) filter (where sku like 'HGS-%')||'|'||count(distinct sku)||'|'||md5(string_agg(id::text||'|'||coalesce(name,'')||'|'||coalesce(sku,'')||'|'||coalesce(price::text,'')||'|'||coalesce(image_url,'')||'|'||coalesce(supplier_id::text,''), ',' order by id)) from public.products)
union all select 24, 'A24 products with an image (expect 524)', (select count(*) from public.products where image_url is not null and btrim(image_url) <> '')::text
) t order by n;

-- QUERY 2 (expect exactly one row: both | 524)
select sales_channel, count(*) from public.products group by 1;
